+                        new BoundTransportAddress(new TransportAddress[] { node.getAddress() }, node.getAddress()),
+                        profileAddresses,
+                        false
+                    ),
+                    null,
+                    null,
+                    null,
+                    null,
+                    null
+                )
+            );
+        }
+
+        final NodesInfoResponse nodesInfoResponse = new NodesInfoResponse(
+            new ClusterName(randomAlphaOfLengthBetween(3, 8)),
+            nodeInfos,
+            List.of()
